#!/usr/bin/env python3
"""Independent check of the atomic monitors and of the product tuple count."""
import importlib.util
import itertools
import json
import random
import subprocess
import sys

spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec)
spec.loader.exec_module(m)


def sem_state(op, p, w):
    """State of the atom monitor after reading w, from the prose definition."""
    mm = len(p)
    if op == 'match':
        if len(w) <= mm and w == p[:len(w)]:
            return len(w)
        return mm + 1
    if op == 'startswith':
        if len(w) >= mm and w[:mm] == p:
            return mm
        if len(w) < mm and w == p[:len(w)]:
            return len(w)
        return mm + 1
    # longest j <= mm with p[:j] suffix of w
    best = 0
    for j in range(min(mm, len(w)), -1, -1):
        if w[len(w) - j:] == p[:j]:
            best = j
            break
    if op == 'endswith':
        return best
    # contains
    for i in range(len(w) - mm + 1):
        if w[i:i + mm] == p:
            return mm
    return best


def check_monitors(seed):
    rnd = random.Random(seed)
    toks = ['a', 'b', 'c', 'd']
    index = {t: i for i, t in enumerate(toks)}
    sigma = len(toks)
    for trial in range(400):
        op = rnd.choice(['match', 'startswith', 'endswith', 'contains'])
        mm = rnd.choice([0, 1, 2, 3, 4, 5])
        p = tuple(rnd.choice(toks) for _ in range(mm))
        if mm and rnd.random() < 0.4:
            p = tuple([p[0]] * mm)
        tables, true_states, widths = m.build_monitors([(op, p)], sigma, index)
        tab = tables[0]
        # walk random words, compare table-driven vs semantic state
        for _ in range(60):
            w = [rnd.choice(toks) for _ in range(rnd.randint(0, 8))]
            st = 0
            for t in w:
                st = tab[index[t]][st]
            want = sem_state(op, list(p), w)
            assert st == want, (op, p, w, st, want)
            # accepting flag
            if op == 'match':
                sem = (w == list(p))
            elif op == 'startswith':
                sem = w[:mm] == list(p) and len(w) >= mm
            elif op == 'endswith':
                sem = len(w) >= mm and w[len(w) - mm:] == list(p)
            else:
                sem = any(w[i:i + mm] == list(p) for i in range(len(w) - mm + 1))
            assert (st == true_states[0]) == sem, (op, p, w, st, sem)


def count_tuples(atoms, sigma, index, cap=10 ** 9):
    """Independent reachable tuple count using the semantic definition."""
    toks = [t for t, i in sorted(index.items(), key=lambda kv: kv[1])]
    seen = {tuple(sem_state(op, list(p), []) for op, p in atoms)}
    frontier = [([], tuple(sem_state(op, list(p), []) for op, p in atoms))]
    while frontier:
        w, tup = frontier.pop()
        for t in toks:
            nw = w + [t]
            nt = tuple(sem_state(op, list(p), nw) for op, p in atoms)
            if nt not in seen:
                seen.add(nt)
                if len(seen) > cap:
                    return len(seen)
                frontier.append((nw, nt))
    return len(seen)


def check_product(seed):
    rnd = random.Random(seed)
    toks = ['a', 'b', 'c', 'd', 'e'][:rnd.randint(1, 4)]
    index = {t: i for i, t in enumerate(toks)}
    sigma = len(toks)
    for trial in range(150):
        k = rnd.randint(1, 4)
        atoms = []
        while len(atoms) < k:
            op = rnd.choice(['match', 'startswith', 'endswith', 'contains'])
            mm = rnd.choice([0, 1, 2, 3])
            p = tuple(rnd.choice(toks) for _ in range(mm))
            if (op, p) not in atoms:
                atoms.append((op, p))
        tables, true_states, widths = m.build_monitors(atoms, sigma, index)
        coltabs = [[tables[j][a] for j in range(k)] for a in range(sigma)]
        states, trans = m.product_bfs(k, coltabs, sigma, 10 ** 9)
        want = count_tuples(atoms, sigma, index)
        assert len(states) == want, (atoms, toks, len(states), want)
        # every transition agrees with the semantic state after the word
        # (reconstruct words by BFS)
        words = {0: []}
        order = [0]
        for q in order:
            for a in range(sigma):
                t = trans[q][a]
                if t not in words:
                    words[t] = words[q] + [toks[a]]
                    order.append(t)
        assert len(words) == len(states)
        for q, w in words.items():
            sem = tuple(sem_state(op, list(p), w) for op, p in atoms)
            assert states[q] == sem, (atoms, w, states[q], sem)


if __name__ == '__main__':
    check_monitors(int(sys.argv[1]) if len(sys.argv) > 1 else 7)
    print('monitors ok')
    check_product(int(sys.argv[2]) if len(sys.argv) > 2 else 11)
    print('product ok')
